mkdir -p /tmp/rls-test && cat > /tmp/rls-test/shim.sql <<'EOF'
create role anon nologin;
create role authenticated nologin;
create schema auth;
create table auth.users (id uuid primary key default gen_random_uuid());
create function auth.uid() returns uuid language sql stable as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
grant usage on schema public to anon, authenticated;
grant all on all tables in schema public to anon, authenticated;
alter default privileges in schema public grant all on tables to anon, authenticated;
grant usage on schema auth to anon, authenticated;
grant execute on function auth.uid() to anon, authenticated;
EOF
cat > /tmp/rls-test/test.sql <<'EOF'
\set ON_ERROR_STOP 0
insert into auth.users (id) values
  ('00000000-0000-0000-0000-00000000000a'),  -- alice: admin of A
  ('00000000-0000-0000-0000-00000000000b'),  -- bob: member of A
  ('00000000-0000-0000-0000-00000000000c'); -- carol: admin of B
insert into public.teams (id, name) values
  ('10000000-0000-0000-0000-00000000000a', 'A'),
  ('10000000-0000-0000-0000-00000000000b', 'B');
insert into public.team_members (team_id, user_id, role) values
  ('10000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000a', 'admin'),
  ('10000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b', 'member'),
  ('10000000-0000-0000-0000-00000000000b', '00000000-0000-0000-0000-00000000000c', 'admin');
insert into public.projects (id, team_id, name) values
  ('20000000-0000-0000-0000-00000000000a', '10000000-0000-0000-0000-00000000000a', 'A-proj'),
  ('20000000-0000-0000-0000-00000000000b', '10000000-0000-0000-0000-00000000000b', 'B-proj');

-- helper: run as role with given user
\echo === SIGNED OUT (anon) ===
set role anon; reset request.jwt.claim.sub;
select 'teams', count(*) from public.teams;
select 'members', count(*) from public.team_members;
select 'projects', count(*) from public.projects;
select 'overview', count(*) from public.project_overview;
reset role;

\echo === BOB (member of A) ===
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
select 'teams', string_agg(name, ',') from public.teams;
select 'members', count(*) from public.team_members;
select 'projects', string_agg(name, ',') from public.projects;
select 'overview', string_agg(name, ',') from public.project_overview;
\echo -- bob cannot insert project in A (not admin): expect ERROR
insert into public.projects (team_id, name) values ('10000000-0000-0000-0000-00000000000a', 'x');
\echo -- bob cannot add member: expect ERROR
insert into public.team_members (team_id, user_id) values ('10000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000c');
\echo -- bob cannot update / delete projects: expect 0 rows
update public.projects set name = 'hacked';
delete from public.projects;
reset role;

\echo === ALICE (admin of A) ===
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
select 'projects', string_agg(name, ',') from public.projects;
insert into public.projects (team_id, name) values ('10000000-0000-0000-0000-00000000000a', 'A-new');
update public.projects set name = 'A-renamed' where name = 'A-new';
\echo -- alice cannot move project into team B: expect ERROR
update public.projects set team_id = '10000000-0000-0000-0000-00000000000b' where name = 'A-renamed';
\echo -- alice cannot write to B: expect ERROR
insert into public.projects (team_id, name) values ('10000000-0000-0000-0000-00000000000b', 'x');
\echo -- alice adds carol? (carol is not in A; add bob as member duplicate ignored) 
insert into public.team_members (team_id, user_id) values ('10000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000c');
select 'members A', count(*) from public.team_members where team_id = '10000000-0000-0000-0000-00000000000a';
delete from public.team_members where user_id = '00000000-0000-0000-0000-00000000000c' and team_id = '10000000-0000-0000-0000-00000000000a';
select 'members A after remove', count(*) from public.team_members where team_id = '10000000-0000-0000-0000-00000000000a';
delete from public.projects where name = 'A-renamed';
\echo -- alice cannot see/delete B: 
select 'B projects seen by alice', count(*) from public.projects where team_id = '10000000-0000-0000-0000-00000000000b';
delete from public.projects where team_id = '10000000-0000-0000-0000-00000000000b';
reset role;

\echo === CAROL (admin of B only) can not touch A ===
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000c';
select 'A projects seen', count(*) from public.projects where team_id = '10000000-0000-0000-0000-00000000000a';
insert into public.team_members (team_id, user_id) values ('10000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000c');
reset role;

\echo === ADMIN FLAG CHECK: bob cannot escalate self by update ===
set role authenticated; set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
update public.team_members set role = 'admin' where user_id = '00000000-0000-0000-0000-00000000000b';
reset role;
select 'bob role after', role from public.team_members where user_id = '00000000-0000-0000-0000-00000000000b';
EOF
cd /tmp/rls-test && docker rm -f rls-pg >/dev/null 2>&1; docker run -d --name rls-pg -e POSTGRES_PASSWORD=pw -p 55432:5432 postgres:16 >/dev/null && for i in $(seq 1 30); do docker exec rls-pg pg_isready -U postgres >/dev/null 2>&1 && break; sleep 1; done; docker cp shim.sql rls-pg:/tmp/shim.sql && docker cp test.sql rls-pg:/tmp/test.sql && docker cp "/private/var/folders/6g/0fzvn88n34q8hbxh7l32npfc0000gn/T/skillshed-bench-supabase-rls-on-2-gawmad/supabase/migrations/20260101000000_init.sql" rls-pg:/tmp/init.sql && docker cp "/private/var/folders/6g/0fzvn88n34q8hbxh7l32npfc0000gn/T/skillshed-bench-supabase-rls-on-2-gawmad/supabase/migrations/20261022120000_row_level_security.sql" rls-pg:/tmp/rls.sql && docker exec rls-pg psql -U postgres -v ON_ERROR_STOP=1 -q -f /tmp/shim.sql -f /tmp/init.sql -f /tmp/rls.sql && echo MIGRATION_APPLIED && docker exec rls-pg psql -U postgres -f /tmp/test.sql 2>&1

